import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.sql.*;
public class W14E01_DatabaseCRUDDemo {
 static final String URL="jdbc:mysql://localhost:3306/swing_tutorial",USER="root",PASSWORD="";static DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Name","Course","Email"},0);static JTable t=new JTable(m);
 static Connection c() throws SQLException{return DriverManager.getConnection(URL,USER,PASSWORD);} static void load(){m.setRowCount(0);try(Connection c=c();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM students ORDER BY id")){while(r.next())m.addRow(new Object[]{r.getInt("id"),r.getString("name"),r.getString("course"),r.getString("email")});}catch(SQLException ex){JOptionPane.showMessageDialog(null,ex.getMessage());}}
 public static void main(String[] args){SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Database CRUD 1");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setSize(860,430);JTextField nameF=new JTextField(10),course=new JTextField(7),email=new JTextField(12);JButton add=new JButton("Create"),del=new JButton("Delete Selected"),refresh=new JButton("Refresh");
 add.addActionListener(e->{try(Connection c=c();PreparedStatement p=c.prepareStatement("INSERT INTO students(name,course,email) VALUES(?,?,?)")){p.setString(1,nameF.getText());p.setString(2,course.getText());p.setString(3,email.getText());p.executeUpdate();load();}catch(SQLException ex){JOptionPane.showMessageDialog(f,ex.getMessage());}});
 del.addActionListener(e->{int r=t.getSelectedRow();if(r>=0)try(Connection c=c();PreparedStatement p=c.prepareStatement("DELETE FROM students WHERE id=?")){p.setInt(1,Integer.parseInt(m.getValueAt(t.convertRowIndexToModel(r),0).toString()));p.executeUpdate();load();}catch(SQLException ex){JOptionPane.showMessageDialog(f,ex.getMessage());}});refresh.addActionListener(e->load());
 JPanel p=new JPanel();p.add(nameF);p.add(course);p.add(email);p.add(add);p.add(del);p.add(refresh);f.add(p,BorderLayout.NORTH);f.add(new JScrollPane(t),BorderLayout.CENTER);load();f.setLocationRelativeTo(null);f.setVisible(true);});}
}
